KG42.register("nodes-b46cf1dff29687aa4c4ed68c",{"id":"KG31-fc19e7c39ea9de54","code":"OMC012.3","label":"Coordination through direct control of aggregated resources","definition":"The coordinator sends control commands to participating resources based on the collective operating state and directly coordinates resource operation to achieve sharing or power balance; incidental market management responsibilities are retained according to the source.","layer":"L4","template_code":"JOC","concept_id":"coordination.local_operator","concept_ids":["coordination.local_operator"],"identity_dimensions":{"identity_fields":["Decision authority: the coordinator directly sends resource operation control commands","Target object: aggregated resources participating in sharing or balancing","Input-output relationship: collective operating state enters control decision-making and forms control signals directed to resources"]},"exclusions":[["ESC organizes customer sharing and import/export balancing with the main grid, and bears price management and settlement management responsibilities","The operator is ESC, the measurement location is PCC, and communication is unidirectional","Coordinates aggregated batteries using PCC net power measurement and sends a common control signal to each battery","Sharing responsibility conditions: P_{BC,t}^i/W_{B,N}^i is equal across batteries, and P_{BD,t}^i/W_{B,N}^i is equal across batteries","Common control is based on community demand and may not act according to an individual prosumer's own net load","ESC is additionally responsible for compensation price adjustment and customer bill management"]],"members":[{"id":"19-two_stage_battery_sharing::v141-c-R001::V::coordination.local_operator","rule_id":"v141-c-R001","market_meaning":"The ESC is responsible for exporting power to or importing power from the main grid to ensure the community's power balance. Scope: ESC responsibility at the community's interface with the main grid in the P2P sharing mechanism. The ESC is responsible for controlling the charging and discharging activities of all batteries and provides control signals to the battery controllers through one-way communication. Scope: ESC-operated aggregated battery control in the P2P sharing community. Under this shared-responsibility rule, the ESC provides each individual battery controller with the same control signal. Scope: The adopted shared-responsibility rule for community battery control. Condition: Battery charging/discharging power normalized to each battery's nominal capacity is assumed to be the same.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"coordination","context_text":"ESC responsibility at the community's interface with the main grid in the P2P sharing mechanism. | ESC-operated aggregated battery control in the P2P sharing community. | The adopted shared-responsibility rule for community battery control.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e002","v141-b-g01-e004","v141-b-g02-E15"]},"constraint_refs":["19-two_stage_battery_sharing::v141-c-R001::v141-c-R001-C001","19-two_stage_battery_sharing::v141-c-R001::v141-c-R001-C002","19-two_stage_battery_sharing::v141-c-R001::v141-c-R001-C003","19-two_stage_battery_sharing::v141-c-R001::v141-c-R001-C004"],"decision_anchor":"coordination.local_operator","source_rule_sha256":"2aac96ef4f0f44bb011b6b109b70d6fe288cb0e050fbfc32b1f22c8189affa38","paper":"19-two_stage_battery_sharing","rule_ref":"19-two_stage_battery_sharing::v141-c-R001","node_id":"coordination.local_operator","function":"coordination.local_operator","unit_id":"19-two_stage_battery_sharing::v141-a-M01::coordination.local_operator","mechanism_id":"v141-a-M01","anchor":true},{"id":"19-two_stage_battery_sharing::v141-c-R002::V::coordination.local_operator","rule_id":"v141-c-R002","market_meaning":"The ESC, acting as the local market operator, coordinates P2P energy sharing between community customers. Scope: P2P energy sharing between customers within the community Microgrid. P2P sharing permits local buying and selling of energy, including PV sharing among prosumers and trades of surplus PV power with consumers without PV systems. Scope: Neighborhood energy exchanges within the P2P sharing community.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"activation","context_text":"Neighborhood energy exchanges within the P2P sharing community. | P2P energy sharing between customers within the community Microgrid.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e002","v141-b-g01-e007"]},"constraint_refs":["19-two_stage_battery_sharing::v141-c-R002::v141-c-R002-C001"],"decision_anchor":"execution.energy_trade","source_rule_sha256":"5db978e98751bde2785e7cf386418bc694dae5876c58c59f0174378d840f5e95","paper":"19-two_stage_battery_sharing","rule_ref":"19-two_stage_battery_sharing::v141-c-R002","node_id":"coordination.local_operator","function":"coordination.local_operator","unit_id":"19-two_stage_battery_sharing::v141-a-M01::coordination.local_operator","mechanism_id":"v141-a-M01","anchor":false},{"id":"19-two_stage_battery_sharing::v141-c-R005::V::coordination.local_operator","rule_id":"v141-c-R005","market_meaning":"The ESC manages and adjusts the compensating price included in the local P2P pricing mechanism. Scope: Community P2P energy sharing under modified SDR pricing; compensation adjustment informed by customer assessment. The P2P buying price should not exceed the grid buying price, and the P2P selling price should not fall below the grid selling price. Scope: Buying and selling prices within the P2P sharing community. P2P pricing is conducted 24 h after actual electricity consumption using recorded import/export energy data from smart meters. Scope: Ex-post pricing within the P2P sharing community. P2P trading prices are calculated using the SDR method, with the dynamic supply and demand ratio obtained from aggregated metered supply and demand. Scope: Community P2P trading prices calculated from the previous 24 h of premises' smart-metering data. The compensating price is bounded between zero and the difference between the grid buying and selling prices. Scope: Compensating component of the community's modified SDR pricing mechanism. Both P2P selling and buying prices equal the price of electricity bought from the main grid. Scope: Community P2P buying and selling prices at time t. Condition: SDR^{t} = 0; there is no selling power in the community. Both P2P selling and buying prices equal the grid selling price plus the compensating price. Scope: Community P2P buying and selling prices at time t. Condition: SDR^{t} = 1; community selling power equals buying power.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"pricing","context_text":"Buying and selling prices within the P2P sharing community. | Community P2P buying and selling prices at time t. | Community P2P energy sharing under modified SDR pricing; compensation adjustment informed by customer assessment. | Community P2P trading prices calculated from the previous 24 h of premises' smart-metering data. | Compensating component of the community's modified SDR pricing mechanism. | Ex-post pricing within the P2P sharing community.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e013","v141-b-g01-e014","v141-b-g02-E10","v141-b-g02-E21","v141-b-g02-E23","v141-b-g04-E12"]},"constraint_refs":["19-two_stage_battery_sharing::v141-c-R005::v141-c-R005-C001"],"decision_anchor":"pricing.local","source_rule_sha256":"96395fa5d5e547fb54dd66802ad10eec3cad2948cbd6c7b49fe199d6b9e43676","paper":"19-two_stage_battery_sharing","rule_ref":"19-two_stage_battery_sharing::v141-c-R005","node_id":"coordination.local_operator","function":"coordination.local_operator","unit_id":"19-two_stage_battery_sharing::v141-a-M01::coordination.local_operator","mechanism_id":"v141-a-M01","anchor":false},{"id":"19-two_stage_battery_sharing::v141-c-R007::V::coordination.local_operator","rule_id":"v141-c-R007","market_meaning":"The ESC administers settlement by calculating individual customer energy bills and ensuring that prosumers’ income balances consumers’ expenditure. Scope: Individual customer settlement in the ESC-operated P2P sharing community. Local P2P pricing determines the electricity bills that prosumers pay or receive as repayments and that consumers pay. Scope: Electricity-bill payments and repayments of prosumers and consumers contracted with the ESC. The source states that the P2P buying-price ceiling implies lower consumer electricity bills under P2P sharing than under P2G trading. Scope: Consumer electricity bills under P2P sharing compared with P2G trading. Condition: The P2P buying price never exceeds the price of electricity bought from the grid. Under this uncompensated pricing case, the source states that prosumer income is undermined while consumers benefit; prosumers may receive less income than without P2P sharing. Scope: The source’s explanation of prosumer income and consumer benefits under uncompensated SDR pricing. Condition: The compensating price is zero and the supply-to-demand ratio exceeds one, so both P2P prices equal the grid selling price. At every studied penetration level, zero compensation is reported to leave some prosumers paying higher electricity bills or receiving lower incomes when participating in P2P sharing. Scope: The reported sensitivity evaluation across the studied penetration levels of PV battery systems. Condition: The compensating price is zero in the reported evaluation. With an appropriate compensating price, modified local SDR pricing is stated to ensure economic benefits for every individual prosumer and consumer, with economic gains described in terms of bill savings or repayments. Scope: Individual prosumer and consumer financial outcomes under modified SDR pricing compared with conventional P2G trading. Condition: The compensating price is appropriately set. Billing is conducted 24 hours after actual electricity consumption using recorded import/export energy data from smart meters, for example half-hourly records. Scope: Customer billing in the proposed two-stage P2P sharing arrangement. The positive value is the amount of electricity bill the prosumer is required to pay. Scope: Prosumer electricity-bill values in the reported financial assessment. Condition: The reported prosumer bill value is positive. The negative value denotes income received by the prosumer. Scope: Prosumer electricity-bill values in the reported financial assessment. Condition: The reported prosumer bill value is negative.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"settlement","context_text":"Consumer electricity bills under P2P sharing compared with P2G trading. | Customer billing in the proposed two-stage P2P sharing arrangement. | Electricity-bill payments and repayments of prosumers and consumers contracted with the ESC. | Individual customer settlement in the ESC-operated P2P sharing community. | Individual prosumer and consumer financial outcomes under modified SDR pricing compared with conventional P2G trading. | Prosumer electricity-bill values in the reported financial assessment. | The reported sensitivity evaluation across the studied penetration levels of PV battery systems. | The source’s explanation of prosumer income and consumer benefits under uncompensated SDR pricing.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e002","v141-b-g01-e004","v141-b-g01-e005","v141-b-g01-e006","v141-b-g01-e013","v141-b-g02-E23","v141-b-g03-E13","v141-b-g04-E10","v141-b-g04-E13","v141-b-g04-E15","v141-b-g04-E17"]},"constraint_refs":["19-two_stage_battery_sharing::v141-c-R007::v141-c-R007-C001"],"decision_anchor":"settlement.payment","source_rule_sha256":"bd880e891130c0f37fb74ec2eeadfc37b72ff840ddc75d6776e532b766029c31","paper":"19-two_stage_battery_sharing","rule_ref":"19-two_stage_battery_sharing::v141-c-R007","node_id":"coordination.local_operator","function":"coordination.local_operator","unit_id":"19-two_stage_battery_sharing::v141-a-M01::coordination.local_operator","mechanism_id":"v141-a-M01","anchor":false}],"paper_ids":["19-two_stage_battery_sharing"],"evidence":[{"evidence_id":"v141-b-g01-e004","location":{"location_id":"src-b91cee592e-p04-c1r4__v141-a-M01-coordination","page":4,"printed_page":"264","section":"2.1. P2P energy sharing structure","anchor_text":"Details of the control framework and the pricing mechanism for the local market are presented in Sec","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"(1) Energy sharing coordinator (ESC)\n• Export power to (or import power from) the main grid to ensure the power balance of the community;\n• Contract with a supplier for the electricity trade at pre-defined exporting/importing prices and ensure the payment balance between the community and the supplier;\n• Control the charging/discharging activities of all batteries;\n• Contract with individual prosumers and consumers according to the P2P pricing mechanism and ensure the prosumers’ income balance with the consumers’ expenditure.","paper":"19-two_stage_battery_sharing","rule_id":"v141-c-R001","quote":"(1) Energy sharing coordinator (ESC)\n• Export power to (or import power from) the main grid to ensure the power balance of the community;\n• Contract with a supplier for the electricity trade at pre-defined exporting/importing prices and ensure the payment balance between the community and the supplier;\n• Control the charging/discharging activities of all batteries;\n• Contract with individual prosumers and consumers according to the P2P pricing mechanism and ensure the prosumers’ income balance with the consumers’ expenditure."},{"evidence_id":"v141-b-g01-e002","location":{"location_id":"src-b91cee592e-p04-c1r3__v141-a-M01-coordination","page":4,"printed_page":"264","section":"2.1. P2P energy sharing structure","anchor_text":"surplus PV power from prosumers can also be traded with consumers who do not have PV systems. PP A t","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"A third party entity named “energy sharing coordinator (ESC)” coordinates between customers and provides P2P sharing services, i.e. assuring the power balance and payment balance [13]. The ESC is the controller of the DERs as well as the local market operator. The ESC is located at the PCC (e.g. the low voltage substation). A smart meter is installed at the PCC, measuring the real-time net power consumption of the community, and this measurement is the input of the ESC. The ESC is communicated with the controllers of these small-scale batteries at the prosumer premises, and provides control signals to them via one-way communication. Through managing the battery charging/discharging, the ESC ensures the maximum use of local energy resources and the minimum amount of electricity fed back into the grid. Therefore the overall energy cost of the community is reduced, and the reduced cost is distributed to individual customers through a P2P pricing mechanism. The ESC also calculates energy bills of individual customers based on the P2P pricing mechanism, using the recorded import/export energy (e.g. half-hourly) from smart meters at the premises.","paper":"19-two_stage_battery_sharing","rule_id":"v141-c-R001","quote":"A third party entity named “energy sharing coordinator (ESC)” coordinates between customers and provides P2P sharing services, i.e. assuring the power balance and payment balance [13]. The ESC is the controller of the DERs as well as the local market operator. The ESC is located at the PCC (e.g. the low voltage substation). A smart meter is installed at the PCC, measuring the real-time net power consumption of the community, and this measurement is the input of the ESC. The ESC is communicated with the controllers of these small-scale batteries at the prosumer premises, and provides control signals to them via one-way communication. Through managing the battery charging/discharging, the ESC ensures the maximum use of local energy resources and the minimum amount of electricity fed back into the grid. Therefore the overall energy cost of the community is reduced, and the reduced cost is distributed to individual customers through a P2P pricing mechanism. The ESC also calculates energy bills of individual customers based on the P2P pricing mechanism, using the recorded import/export energy (e.g. half-hourly) from smart meters at the premises."},{"evidence_id":"v141-b-g02-E15","location":{"location_id":"src-b91cee592e-p07-c2r2__v141-a-M01-clearing","page":7,"printed_page":null,"section":null,"anchor_text":"y g g their batteries. By taking the shared responsibility, the battery charging/dischar- ging power","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"definition"},"source_text":"A rule was taken that when the community has surplus energy, the prosumers share their responsibilities by charging their batteries in an amount which is in a linear relation to the size (i.e. nominal capacity) of their batteries. Vice versa, when the community consumes electricity, the prosumers share their responsibility by discharging their batteries in an amount which is linear to the size of their batteries. By taking the shared responsibility, the battery charging/discharging power normalized to the nominal capacity of each battery was assumed to be the same. Therefore, the ESC provides each individual battery controller with the same control signal. This means that all batteries are approximately at the same SOC. In practice, some batteries reach the maximum or minimum SOC earlier than others, due to differences in the aging conditions of batteries and inverters. However, this does not affect the control strategy as the control signal depends on the real time measurement at the PCC. The battery controller only receives control signals from the ESC, disregarding the prosumer's own net load. For example, a battery can be discharging whilst the prosumer has surplus PV generation. This is because the energy is required and consumed by his neighbors.","paper":"19-two_stage_battery_sharing","rule_id":"v141-c-R001","quote":"A rule was taken that when the community has surplus energy, the prosumers share their responsibilities by charging their batteries in an amount which is in a linear relation to the size (i.e. nominal capacity) of their batteries. Vice versa, when the community consumes electricity, the prosumers share their responsibility by discharging their batteries in an amount which is linear to the size of their batteries. By taking the shared responsibility, the battery charging/discharging power normalized to the nominal capacity of each battery was assumed to be the same. Therefore, the ESC provides each individual battery controller with the same control signal. This means that all batteries are approximately at the same SOC. In practice, some batteries reach the maximum or minimum SOC earlier than others, due to differences in the aging conditions of batteries and inverters. However, this does not affect the control strategy as the control signal depends on the real time measurement at the PCC. The battery controller only receives control signals from the ESC, disregarding the prosumer's own net load. For example, a battery can be discharging whilst the prosumer has surplus PV generation. This is because the energy is required and consumed by his neighbors."},{"evidence_id":"v141-b-g01-e002","location":{"location_id":"src-b91cee592e-p04-c1r3__v141-a-M01-coordination","page":4,"printed_page":"264","section":"2.1. P2P energy sharing structure","anchor_text":"surplus PV power from prosumers can also be traded with consumers who do not have PV systems. PP A t","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"A third party entity named “energy sharing coordinator (ESC)” coordinates between customers and provides P2P sharing services, i.e. assuring the power balance and payment balance [13]. The ESC is the controller of the DERs as well as the local market operator. The ESC is located at the PCC (e.g. the low voltage substation). A smart meter is installed at the PCC, measuring the real-time net power consumption of the community, and this measurement is the input of the ESC. The ESC is communicated with the controllers of these small-scale batteries at the prosumer premises, and provides control signals to them via one-way communication. Through managing the battery charging/discharging, the ESC ensures the maximum use of local energy resources and the minimum amount of electricity fed back into the grid. Therefore the overall energy cost of the community is reduced, and the reduced cost is distributed to individual customers through a P2P pricing mechanism. The ESC also calculates energy bills of individual customers based on the P2P pricing mechanism, using the recorded import/export energy (e.g. half-hourly) from smart meters at the premises.","paper":"19-two_stage_battery_sharing","rule_id":"v141-c-R002","quote":"A third party entity named “energy sharing coordinator (ESC)” coordinates between customers and provides P2P sharing services, i.e. assuring the power balance and payment balance [13]. The ESC is the controller of the DERs as well as the local market operator. The ESC is located at the PCC (e.g. the low voltage substation). A smart meter is installed at the PCC, measuring the real-time net power consumption of the community, and this measurement is the input of the ESC. The ESC is communicated with the controllers of these small-scale batteries at the prosumer premises, and provides control signals to them via one-way communication. Through managing the battery charging/discharging, the ESC ensures the maximum use of local energy resources and the minimum amount of electricity fed back into the grid. Therefore the overall energy cost of the community is reduced, and the reduced cost is distributed to individual customers through a P2P pricing mechanism. The ESC also calculates energy bills of individual customers based on the P2P pricing mechanism, using the recorded import/export energy (e.g. half-hourly) from smart meters at the premises."},{"evidence_id":"v141-b-g01-e014","location":{"location_id":"src-b91cee592e-p03-c2r4__v141-a-M01-participation","page":3,"printed_page":"263","section":"1. Introduction","anchor_text":"m DERs, because the pricing and billing are conducted 24 h after the ng actual electricity consumpti","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"restatement"},"source_text":"An innovative P2P pricing mechanism was developed to ensure all customers in a community gain economic benefits, i.e. being better off compared to the conventional P2G trading. This pricing mechanism is modified from a previous SDR mechanism to include a compensating price. The modified pricing mechanism can be used as a benchmark applicable to any P2P energy sharing model.","paper":"19-two_stage_battery_sharing","rule_id":"v141-c-R005","quote":"An innovative P2P pricing mechanism was developed to ensure all customers in a community gain economic benefits, i.e. being better off compared to the conventional P2G trading. This pricing mechanism is modified from a previous SDR mechanism to include a compensating price. The modified pricing mechanism can be used as a benchmark applicable to any P2P energy sharing model."},{"evidence_id":"v141-b-g02-E10","location":{"location_id":"src-b91cee592e-p06-c1r2__v141-a-M01-coordination","page":6,"printed_page":null,"section":null,"anchor_text":"psumer premises. The purposes of the control is to minimize the amount of electricity fed back to th","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"definition"},"source_text":"In the second block, the smart metering data at all the premises in the community are collected to calculate the aggregated supply and demand at different times of the day (for the previous 24 h). The dynamic supply and demand ratio is used to calculate the P2P trading prices using the SDR method. In practice, this is done 24 h after the actual electricity consumption, and therefore there are no iterations between the pricing and control activities. Finally, the assessment of the P2P energy sharing is carried out. In the community level, the self-consumption and self-sufficiency rate of the community, and the energy cost are analyzed. In the individual customer level, the energy cost of each customer is calculated and a participating willingness index is introduced to evaluate the willingness of prosumers participating in P2P energy sharing. This in turn helps the ESC to adjust the compensating price, which is used to ensure all customers in the community gain economic benefit.","paper":"19-two_stage_battery_sharing","rule_id":"v141-c-R005","quote":"In the second block, the smart metering data at all the premises in the community are collected to calculate the aggregated supply and demand at different times of the day (for the previous 24 h). The dynamic supply and demand ratio is used to calculate the P2P trading prices using the SDR method. In practice, this is done 24 h after the actual electricity consumption, and therefore there are no iterations between the pricing and control activities. Finally, the assessment of the P2P energy sharing is carried out. In the community level, the self-consumption and self-sufficiency rate of the community, and the energy cost are analyzed. In the individual customer level, the energy cost of each customer is calculated and a participating willingness index is introduced to evaluate the willingness of prosumers participating in P2P energy sharing. This in turn helps the ESC to adjust the compensating price, which is used to ensure all customers in the community gain economic benefit."},{"evidence_id":"v141-b-g04-E12","location":{"location_id":"src-b91cee592e-p14-c1r4__v141-a-M01-participation","page":14,"printed_page":null,"section":null,"anchor_text":"participation willingness, the lowest compensating prices were 4, 3.5, en 6, 8.5 and 7.5 pence, resp","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-14.png","occurrence_role":"condition"},"source_text":"Therefore, the penetration level of the PV battery systems in a community and the compensating prices managed by the ESC are the main factors to impact the participating willingness for P2P energy sharing, and they should be considered by prosumers and energy service companies when they initialize for P2P energy sharing.","paper":"19-two_stage_battery_sharing","rule_id":"v141-c-R005","quote":"Therefore, the penetration level of the PV battery systems in a community and the compensating prices managed by the ESC are the main factors to impact the participating willingness for P2P energy sharing, and they should be considered by prosumers and energy service companies when they initialize for P2P energy sharing."},{"evidence_id":"v141-b-g01-e002","location":{"location_id":"src-b91cee592e-p04-c1r3__v141-a-M01-coordination","page":4,"printed_page":"264","section":"2.1. P2P energy sharing structure","anchor_text":"surplus PV power from prosumers can also be traded with consumers who do not have PV systems. PP A t","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"A third party entity named “energy sharing coordinator (ESC)” coordinates between customers and provides P2P sharing services, i.e. assuring the power balance and payment balance [13]. The ESC is the controller of the DERs as well as the local market operator. The ESC is located at the PCC (e.g. the low voltage substation). A smart meter is installed at the PCC, measuring the real-time net power consumption of the community, and this measurement is the input of the ESC. The ESC is communicated with the controllers of these small-scale batteries at the prosumer premises, and provides control signals to them via one-way communication. Through managing the battery charging/discharging, the ESC ensures the maximum use of local energy resources and the minimum amount of electricity fed back into the grid. Therefore the overall energy cost of the community is reduced, and the reduced cost is distributed to individual customers through a P2P pricing mechanism. The ESC also calculates energy bills of individual customers based on the P2P pricing mechanism, using the recorded import/export energy (e.g. half-hourly) from smart meters at the premises.","paper":"19-two_stage_battery_sharing","rule_id":"v141-c-R007","quote":"A third party entity named “energy sharing coordinator (ESC)” coordinates between customers and provides P2P sharing services, i.e. assuring the power balance and payment balance [13]. The ESC is the controller of the DERs as well as the local market operator. The ESC is located at the PCC (e.g. the low voltage substation). A smart meter is installed at the PCC, measuring the real-time net power consumption of the community, and this measurement is the input of the ESC. The ESC is communicated with the controllers of these small-scale batteries at the prosumer premises, and provides control signals to them via one-way communication. Through managing the battery charging/discharging, the ESC ensures the maximum use of local energy resources and the minimum amount of electricity fed back into the grid. Therefore the overall energy cost of the community is reduced, and the reduced cost is distributed to individual customers through a P2P pricing mechanism. The ESC also calculates energy bills of individual customers based on the P2P pricing mechanism, using the recorded import/export energy (e.g. half-hourly) from smart meters at the premises."},{"evidence_id":"v141-b-g01-e004","location":{"location_id":"src-b91cee592e-p04-c1r4__v141-a-M01-coordination","page":4,"printed_page":"264","section":"2.1. P2P energy sharing structure","anchor_text":"Details of the control framework and the pricing mechanism for the local market are presented in Sec","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"(1) Energy sharing coordinator (ESC)\n• Export power to (or import power from) the main grid to ensure the power balance of the community;\n• Contract with a supplier for the electricity trade at pre-defined exporting/importing prices and ensure the payment balance between the community and the supplier;\n• Control the charging/discharging activities of all batteries;\n• Contract with individual prosumers and consumers according to the P2P pricing mechanism and ensure the prosumers’ income balance with the consumers’ expenditure.","paper":"19-two_stage_battery_sharing","rule_id":"v141-c-R007","quote":"(1) Energy sharing coordinator (ESC)\n• Export power to (or import power from) the main grid to ensure the power balance of the community;\n• Contract with a supplier for the electricity trade at pre-defined exporting/importing prices and ensure the payment balance between the community and the supplier;\n• Control the charging/discharging activities of all batteries;\n• Contract with individual prosumers and consumers according to the P2P pricing mechanism and ensure the prosumers’ income balance with the consumers’ expenditure."}],"candidate_only":true,"classification_subtypes":["operator_control_coordination"],"projection_statuses":["clear"],"taxonomy":{"primary_family":"KG31-L4-SC-L4-f7de14ccfeeb7f3d","secondary_families":[],"stage":"L4","ontological_kind":"SC-L4-f7de14ccfeeb7f3d"},"semantic_definition":{"definition":"The coordinator sends control commands to participating resources based on the collective operating state and directly coordinates resource operation to achieve sharing or power balance; incidental market management responsibilities are retained according to the source.","identity_fields":["Decision authority: the coordinator directly sends resource operation control commands","Target object: aggregated resources participating in sharing or balancing","Input-output relationship: collective operating state enters control decision-making and forms control signals directed to resources"]},"source_units":[{"unit_id":"19-two_stage_battery_sharing::v141-a-M01::coordination.local_operator","paper_id":"19-two_stage_battery_sharing","mechanism_id":"v141-a-M01","function":"coordination.local_operator","source_occurrences":[{"id":"19-two_stage_battery_sharing::v141-c-R001::V::coordination.local_operator","rule_id":"v141-c-R001","market_meaning":"The ESC is responsible for exporting power to or importing power from the main grid to ensure the community's power balance. Scope: ESC responsibility at the community's interface with the main grid in the P2P sharing mechanism. The ESC is responsible for controlling the charging and discharging activities of all batteries and provides control signals to the battery controllers through one-way communication. Scope: ESC-operated aggregated battery control in the P2P sharing community. Under this shared-responsibility rule, the ESC provides each individual battery controller with the same control signal. Scope: The adopted shared-responsibility rule for community battery control. Condition: Battery charging/discharging power normalized to each battery's nominal capacity is assumed to be the same.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"coordination","context_text":"ESC responsibility at the community's interface with the main grid in the P2P sharing mechanism. | ESC-operated aggregated battery control in the P2P sharing community. | The adopted shared-responsibility rule for community battery control.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e002","v141-b-g01-e004","v141-b-g02-E15"]},"constraint_refs":["19-two_stage_battery_sharing::v141-c-R001::v141-c-R001-C001","19-two_stage_battery_sharing::v141-c-R001::v141-c-R001-C002","19-two_stage_battery_sharing::v141-c-R001::v141-c-R001-C003","19-two_stage_battery_sharing::v141-c-R001::v141-c-R001-C004"],"decision_anchor":"coordination.local_operator","source_rule_sha256":"2aac96ef4f0f44bb011b6b109b70d6fe288cb0e050fbfc32b1f22c8189affa38"},{"id":"19-two_stage_battery_sharing::v141-c-R002::V::coordination.local_operator","rule_id":"v141-c-R002","market_meaning":"The ESC, acting as the local market operator, coordinates P2P energy sharing between community customers. Scope: P2P energy sharing between customers within the community Microgrid. P2P sharing permits local buying and selling of energy, including PV sharing among prosumers and trades of surplus PV power with consumers without PV systems. Scope: Neighborhood energy exchanges within the P2P sharing community.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"activation","context_text":"Neighborhood energy exchanges within the P2P sharing community. | P2P energy sharing between customers within the community Microgrid.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e002","v141-b-g01-e007"]},"constraint_refs":["19-two_stage_battery_sharing::v141-c-R002::v141-c-R002-C001"],"decision_anchor":"execution.energy_trade","source_rule_sha256":"5db978e98751bde2785e7cf386418bc694dae5876c58c59f0174378d840f5e95"},{"id":"19-two_stage_battery_sharing::v141-c-R005::V::coordination.local_operator","rule_id":"v141-c-R005","market_meaning":"The ESC manages and adjusts the compensating price included in the local P2P pricing mechanism. Scope: Community P2P energy sharing under modified SDR pricing; compensation adjustment informed by customer assessment. The P2P buying price should not exceed the grid buying price, and the P2P selling price should not fall below the grid selling price. Scope: Buying and selling prices within the P2P sharing community. P2P pricing is conducted 24 h after actual electricity consumption using recorded import/export energy data from smart meters. Scope: Ex-post pricing within the P2P sharing community. P2P trading prices are calculated using the SDR method, with the dynamic supply and demand ratio obtained from aggregated metered supply and demand. Scope: Community P2P trading prices calculated from the previous 24 h of premises' smart-metering data. The compensating price is bounded between zero and the difference between the grid buying and selling prices. Scope: Compensating component of the community's modified SDR pricing mechanism. Both P2P selling and buying prices equal the price of electricity bought from the main grid. Scope: Community P2P buying and selling prices at time t. Condition: SDR^{t} = 0; there is no selling power in the community. Both P2P selling and buying prices equal the grid selling price plus the compensating price. Scope: Community P2P buying and selling prices at time t. Condition: SDR^{t} = 1; community selling power equals buying power.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"pricing","context_text":"Buying and selling prices within the P2P sharing community. | Community P2P buying and selling prices at time t. | Community P2P energy sharing under modified SDR pricing; compensation adjustment informed by customer assessment. | Community P2P trading prices calculated from the previous 24 h of premises' smart-metering data. | Compensating component of the community's modified SDR pricing mechanism. | Ex-post pricing within the P2P sharing community.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e013","v141-b-g01-e014","v141-b-g02-E10","v141-b-g02-E21","v141-b-g02-E23","v141-b-g04-E12"]},"constraint_refs":["19-two_stage_battery_sharing::v141-c-R005::v141-c-R005-C001"],"decision_anchor":"pricing.local","source_rule_sha256":"96395fa5d5e547fb54dd66802ad10eec3cad2948cbd6c7b49fe199d6b9e43676"},{"id":"19-two_stage_battery_sharing::v141-c-R007::V::coordination.local_operator","rule_id":"v141-c-R007","market_meaning":"The ESC administers settlement by calculating individual customer energy bills and ensuring that prosumers’ income balances consumers’ expenditure. Scope: Individual customer settlement in the ESC-operated P2P sharing community. Local P2P pricing determines the electricity bills that prosumers pay or receive as repayments and that consumers pay. Scope: Electricity-bill payments and repayments of prosumers and consumers contracted with the ESC. The source states that the P2P buying-price ceiling implies lower consumer electricity bills under P2P sharing than under P2G trading. Scope: Consumer electricity bills under P2P sharing compared with P2G trading. Condition: The P2P buying price never exceeds the price of electricity bought from the grid. Under this uncompensated pricing case, the source states that prosumer income is undermined while consumers benefit; prosumers may receive less income than without P2P sharing. Scope: The source’s explanation of prosumer income and consumer benefits under uncompensated SDR pricing. Condition: The compensating price is zero and the supply-to-demand ratio exceeds one, so both P2P prices equal the grid selling price. At every studied penetration level, zero compensation is reported to leave some prosumers paying higher electricity bills or receiving lower incomes when participating in P2P sharing. Scope: The reported sensitivity evaluation across the studied penetration levels of PV battery systems. Condition: The compensating price is zero in the reported evaluation. With an appropriate compensating price, modified local SDR pricing is stated to ensure economic benefits for every individual prosumer and consumer, with economic gains described in terms of bill savings or repayments. Scope: Individual prosumer and consumer financial outcomes under modified SDR pricing compared with conventional P2G trading. Condition: The compensating price is appropriately set. Billing is conducted 24 hours after actual electricity consumption using recorded import/export energy data from smart meters, for example half-hourly records. Scope: Customer billing in the proposed two-stage P2P sharing arrangement. The positive value is the amount of electricity bill the prosumer is required to pay. Scope: Prosumer electricity-bill values in the reported financial assessment. Condition: The reported prosumer bill value is positive. The negative value denotes income received by the prosumer. Scope: Prosumer electricity-bill values in the reported financial assessment. Condition: The reported prosumer bill value is negative.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"settlement","context_text":"Consumer electricity bills under P2P sharing compared with P2G trading. | Customer billing in the proposed two-stage P2P sharing arrangement. | Electricity-bill payments and repayments of prosumers and consumers contracted with the ESC. | Individual customer settlement in the ESC-operated P2P sharing community. | Individual prosumer and consumer financial outcomes under modified SDR pricing compared with conventional P2G trading. | Prosumer electricity-bill values in the reported financial assessment. | The reported sensitivity evaluation across the studied penetration levels of PV battery systems. | The source’s explanation of prosumer income and consumer benefits under uncompensated SDR pricing.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e002","v141-b-g01-e004","v141-b-g01-e005","v141-b-g01-e006","v141-b-g01-e013","v141-b-g02-E23","v141-b-g03-E13","v141-b-g04-E10","v141-b-g04-E13","v141-b-g04-E15","v141-b-g04-E17"]},"constraint_refs":["19-two_stage_battery_sharing::v141-c-R007::v141-c-R007-C001"],"decision_anchor":"settlement.payment","source_rule_sha256":"bd880e891130c0f37fb74ec2eeadfc37b72ff840ddc75d6776e532b766029c31"}],"constraints":[{"constraint_id":"v141-c-R001-C001","kind":"procedural","role":"core","statement":"The ESC is responsible for exporting power to or importing power from the main grid to ensure the community's power balance. Scope: ESC responsibility at the community's interface with the main grid in the P2P sharing mechanism.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e004"],"ref":"19-two_stage_battery_sharing::v141-c-R001::v141-c-R001-C001","source_rule_id":"v141-c-R001","evidence":[{"evidence_id":"v141-b-g01-e004","location":{"location_id":"src-b91cee592e-p04-c1r4__v141-a-M01-coordination","page":4,"printed_page":"264","section":"2.1. P2P energy sharing structure","anchor_text":"Details of the control framework and the pricing mechanism for the local market are presented in Sec","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"(1) Energy sharing coordinator (ESC)\n• Export power to (or import power from) the main grid to ensure the power balance of the community;\n• Contract with a supplier for the electricity trade at pre-defined exporting/importing prices and ensure the payment balance between the community and the supplier;\n• Control the charging/discharging activities of all batteries;\n• Contract with individual prosumers and consumers according to the P2P pricing mechanism and ensure the prosumers’ income balance with the consumers’ expenditure."}]},{"constraint_id":"v141-c-R001-C002","kind":"procedural","role":"core","statement":"The ESC is responsible for controlling the charging and discharging activities of all batteries and provides control signals to the battery controllers through one-way communication. Scope: ESC-operated aggregated battery control in the P2P sharing community.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e002","v141-b-g01-e004"],"ref":"19-two_stage_battery_sharing::v141-c-R001::v141-c-R001-C002","source_rule_id":"v141-c-R001","evidence":[{"evidence_id":"v141-b-g01-e002","location":{"location_id":"src-b91cee592e-p04-c1r3__v141-a-M01-coordination","page":4,"printed_page":"264","section":"2.1. P2P energy sharing structure","anchor_text":"surplus PV power from prosumers can also be traded with consumers who do not have PV systems. PP A t","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"A third party entity named “energy sharing coordinator (ESC)” coordinates between customers and provides P2P sharing services, i.e. assuring the power balance and payment balance [13]. The ESC is the controller of the DERs as well as the local market operator. The ESC is located at the PCC (e.g. the low voltage substation). A smart meter is installed at the PCC, measuring the real-time net power consumption of the community, and this measurement is the input of the ESC. The ESC is communicated with the controllers of these small-scale batteries at the prosumer premises, and provides control signals to them via one-way communication. Through managing the battery charging/discharging, the ESC ensures the maximum use of local energy resources and the minimum amount of electricity fed back into the grid. Therefore the overall energy cost of the community is reduced, and the reduced cost is distributed to individual customers through a P2P pricing mechanism. The ESC also calculates energy bills of individual customers based on the P2P pricing mechanism, using the recorded import/export energy (e.g. half-hourly) from smart meters at the premises."},{"evidence_id":"v141-b-g01-e004","location":{"location_id":"src-b91cee592e-p04-c1r4__v141-a-M01-coordination","page":4,"printed_page":"264","section":"2.1. P2P energy sharing structure","anchor_text":"Details of the control framework and the pricing mechanism for the local market are presented in Sec","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"(1) Energy sharing coordinator (ESC)\n• Export power to (or import power from) the main grid to ensure the power balance of the community;\n• Contract with a supplier for the electricity trade at pre-defined exporting/importing prices and ensure the payment balance between the community and the supplier;\n• Control the charging/discharging activities of all batteries;\n• Contract with individual prosumers and consumers according to the P2P pricing mechanism and ensure the prosumers’ income balance with the consumers’ expenditure."}]},{"constraint_id":"v141-c-R001-C003","kind":"procedural","role":"core","statement":"Under this shared-responsibility rule, the ESC provides each individual battery controller with the same control signal. Scope: The adopted shared-responsibility rule for community battery control. Condition: Battery charging/discharging power normalized to each battery's nominal capacity is assumed to be the same.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-E15"],"ref":"19-two_stage_battery_sharing::v141-c-R001::v141-c-R001-C003","source_rule_id":"v141-c-R001","evidence":[{"evidence_id":"v141-b-g02-E15","location":{"location_id":"src-b91cee592e-p07-c2r2__v141-a-M01-clearing","page":7,"printed_page":null,"section":null,"anchor_text":"y g g their batteries. By taking the shared responsibility, the battery charging/dischar- ging power","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"definition"},"source_text":"A rule was taken that when the community has surplus energy, the prosumers share their responsibilities by charging their batteries in an amount which is in a linear relation to the size (i.e. nominal capacity) of their batteries. Vice versa, when the community consumes electricity, the prosumers share their responsibility by discharging their batteries in an amount which is linear to the size of their batteries. By taking the shared responsibility, the battery charging/discharging power normalized to the nominal capacity of each battery was assumed to be the same. Therefore, the ESC provides each individual battery controller with the same control signal. This means that all batteries are approximately at the same SOC. In practice, some batteries reach the maximum or minimum SOC earlier than others, due to differences in the aging conditions of batteries and inverters. However, this does not affect the control strategy as the control signal depends on the real time measurement at the PCC. The battery controller only receives control signals from the ESC, disregarding the prosumer's own net load. For example, a battery can be discharging whilst the prosumer has surplus PV generation. This is because the energy is required and consumed by his neighbors."}]},{"constraint_id":"v141-c-R001-C004","kind":"mathematical","role":"core","statement":"Under the shared-responsibility rule, charging power normalized by nominal capacity is equal across prosumer batteries, and discharging power normalized by nominal capacity is equal across prosumer batteries, at each time slot.","expression":"\\frac{P_{BC,t}^{i}}{W_{B,N}^{i}}=\\frac{P_{BC,t}^{j}}{W_{B,N}^{j}},\\qquad \\frac{P_{BD,t}^{i}}{W_{B,N}^{i}}=\\frac{P_{BD,t}^{j}}{W_{B,N}^{j}},\\quad \\forall i,j\\in\\{1,\\ldots,N_B\\},\\ \\forall t\\in\\{1,\\ldots,T\\}","formalization_origin":"source","template_id":null,"members":["coordination.local_operator"],"variable_refs":["v141-c-R001-x001","v141-c-R001-x002"],"parameter_refs":["v141-c-R001-theta001"],"evidence_ids":["v141-b-g02-E15"],"ref":"19-two_stage_battery_sharing::v141-c-R001::v141-c-R001-C004","source_rule_id":"v141-c-R001","evidence":[{"evidence_id":"v141-b-g02-E15","location":{"location_id":"src-b91cee592e-p07-c2r2__v141-a-M01-clearing","page":7,"printed_page":null,"section":null,"anchor_text":"y g g their batteries. By taking the shared responsibility, the battery charging/dischar- ging power","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"definition"},"source_text":"A rule was taken that when the community has surplus energy, the prosumers share their responsibilities by charging their batteries in an amount which is in a linear relation to the size (i.e. nominal capacity) of their batteries. Vice versa, when the community consumes electricity, the prosumers share their responsibility by discharging their batteries in an amount which is linear to the size of their batteries. By taking the shared responsibility, the battery charging/discharging power normalized to the nominal capacity of each battery was assumed to be the same. Therefore, the ESC provides each individual battery controller with the same control signal. This means that all batteries are approximately at the same SOC. In practice, some batteries reach the maximum or minimum SOC earlier than others, due to differences in the aging conditions of batteries and inverters. However, this does not affect the control strategy as the control signal depends on the real time measurement at the PCC. The battery controller only receives control signals from the ESC, disregarding the prosumer's own net load. For example, a battery can be discharging whilst the prosumer has surplus PV generation. This is because the energy is required and consumed by his neighbors."}]},{"constraint_id":"v141-c-R002-C001","kind":"procedural","role":"core","statement":"The ESC, acting as the local market operator, coordinates P2P energy sharing between community customers. Scope: P2P energy sharing between customers within the community Microgrid.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator","execution.energy_trade"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e002"],"ref":"19-two_stage_battery_sharing::v141-c-R002::v141-c-R002-C001","source_rule_id":"v141-c-R002","evidence":[{"evidence_id":"v141-b-g01-e002","location":{"location_id":"src-b91cee592e-p04-c1r3__v141-a-M01-coordination","page":4,"printed_page":"264","section":"2.1. P2P energy sharing structure","anchor_text":"surplus PV power from prosumers can also be traded with consumers who do not have PV systems. PP A t","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"A third party entity named “energy sharing coordinator (ESC)” coordinates between customers and provides P2P sharing services, i.e. assuring the power balance and payment balance [13]. The ESC is the controller of the DERs as well as the local market operator. The ESC is located at the PCC (e.g. the low voltage substation). A smart meter is installed at the PCC, measuring the real-time net power consumption of the community, and this measurement is the input of the ESC. The ESC is communicated with the controllers of these small-scale batteries at the prosumer premises, and provides control signals to them via one-way communication. Through managing the battery charging/discharging, the ESC ensures the maximum use of local energy resources and the minimum amount of electricity fed back into the grid. Therefore the overall energy cost of the community is reduced, and the reduced cost is distributed to individual customers through a P2P pricing mechanism. The ESC also calculates energy bills of individual customers based on the P2P pricing mechanism, using the recorded import/export energy (e.g. half-hourly) from smart meters at the premises."}]},{"constraint_id":"v141-c-R005-C001","kind":"procedural","role":"core","statement":"The ESC manages and adjusts the compensating price included in the local P2P pricing mechanism. Scope: Community P2P energy sharing under modified SDR pricing; compensation adjustment informed by customer assessment.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator","pricing.local"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e014","v141-b-g02-E10","v141-b-g04-E12"],"ref":"19-two_stage_battery_sharing::v141-c-R005::v141-c-R005-C001","source_rule_id":"v141-c-R005","evidence":[{"evidence_id":"v141-b-g01-e014","location":{"location_id":"src-b91cee592e-p03-c2r4__v141-a-M01-participation","page":3,"printed_page":"263","section":"1. Introduction","anchor_text":"m DERs, because the pricing and billing are conducted 24 h after the ng actual electricity consumpti","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"restatement"},"source_text":"An innovative P2P pricing mechanism was developed to ensure all customers in a community gain economic benefits, i.e. being better off compared to the conventional P2G trading. This pricing mechanism is modified from a previous SDR mechanism to include a compensating price. The modified pricing mechanism can be used as a benchmark applicable to any P2P energy sharing model."},{"evidence_id":"v141-b-g02-E10","location":{"location_id":"src-b91cee592e-p06-c1r2__v141-a-M01-coordination","page":6,"printed_page":null,"section":null,"anchor_text":"psumer premises. The purposes of the control is to minimize the amount of electricity fed back to th","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"definition"},"source_text":"In the second block, the smart metering data at all the premises in the community are collected to calculate the aggregated supply and demand at different times of the day (for the previous 24 h). The dynamic supply and demand ratio is used to calculate the P2P trading prices using the SDR method. In practice, this is done 24 h after the actual electricity consumption, and therefore there are no iterations between the pricing and control activities. Finally, the assessment of the P2P energy sharing is carried out. In the community level, the self-consumption and self-sufficiency rate of the community, and the energy cost are analyzed. In the individual customer level, the energy cost of each customer is calculated and a participating willingness index is introduced to evaluate the willingness of prosumers participating in P2P energy sharing. This in turn helps the ESC to adjust the compensating price, which is used to ensure all customers in the community gain economic benefit."},{"evidence_id":"v141-b-g04-E12","location":{"location_id":"src-b91cee592e-p14-c1r4__v141-a-M01-participation","page":14,"printed_page":null,"section":null,"anchor_text":"participation willingness, the lowest compensating prices were 4, 3.5, en 6, 8.5 and 7.5 pence, resp","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-14.png","occurrence_role":"condition"},"source_text":"Therefore, the penetration level of the PV battery systems in a community and the compensating prices managed by the ESC are the main factors to impact the participating willingness for P2P energy sharing, and they should be considered by prosumers and energy service companies when they initialize for P2P energy sharing."}]},{"constraint_id":"v141-c-R007-C001","kind":"procedural","role":"core","statement":"The ESC administers settlement by calculating individual customer energy bills and ensuring that prosumers’ income balances consumers’ expenditure. Scope: Individual customer settlement in the ESC-operated P2P sharing community.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator","settlement.payment"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e002","v141-b-g01-e004"],"ref":"19-two_stage_battery_sharing::v141-c-R007::v141-c-R007-C001","source_rule_id":"v141-c-R007","evidence":[{"evidence_id":"v141-b-g01-e002","location":{"location_id":"src-b91cee592e-p04-c1r3__v141-a-M01-coordination","page":4,"printed_page":"264","section":"2.1. P2P energy sharing structure","anchor_text":"surplus PV power from prosumers can also be traded with consumers who do not have PV systems. PP A t","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"A third party entity named “energy sharing coordinator (ESC)” coordinates between customers and provides P2P sharing services, i.e. assuring the power balance and payment balance [13]. The ESC is the controller of the DERs as well as the local market operator. The ESC is located at the PCC (e.g. the low voltage substation). A smart meter is installed at the PCC, measuring the real-time net power consumption of the community, and this measurement is the input of the ESC. The ESC is communicated with the controllers of these small-scale batteries at the prosumer premises, and provides control signals to them via one-way communication. Through managing the battery charging/discharging, the ESC ensures the maximum use of local energy resources and the minimum amount of electricity fed back into the grid. Therefore the overall energy cost of the community is reduced, and the reduced cost is distributed to individual customers through a P2P pricing mechanism. The ESC also calculates energy bills of individual customers based on the P2P pricing mechanism, using the recorded import/export energy (e.g. half-hourly) from smart meters at the premises."},{"evidence_id":"v141-b-g01-e004","location":{"location_id":"src-b91cee592e-p04-c1r4__v141-a-M01-coordination","page":4,"printed_page":"264","section":"2.1. P2P energy sharing structure","anchor_text":"Details of the control framework and the pricing mechanism for the local market are presented in Sec","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"(1) Energy sharing coordinator (ESC)\n• Export power to (or import power from) the main grid to ensure the power balance of the community;\n• Contract with a supplier for the electricity trade at pre-defined exporting/importing prices and ensure the payment balance between the community and the supplier;\n• Control the charging/discharging activities of all batteries;\n• Contract with individual prosumers and consumers according to the P2P pricing mechanism and ensure the prosumers’ income balance with the consumers’ expenditure."}]}],"variables":[{"variable_id":"v141-c-R001-x001","symbol":"P_{BC,t}^{i}","meaning":"Charging power of the ith battery at time t, controlled by the ESC through the shared-responsibility battery control signal.","kind":"operational","domain":"Nonnegative real charging power (kW) within the source-stated inverter limit (Eq. (7)).","unit":"kW","indices":["i","t"],"evidence_ids":["v141-b-g01-e009","v141-b-g01-e011","v141-b-g02-E15"],"source_rule_id":"v141-c-R001","declaration_ref":"19-two_stage_battery_sharing::v141-c-R001::x::v141-c-R001-x001"},{"variable_id":"v141-c-R001-x002","symbol":"P_{BD,t}^{i}","meaning":"Discharging power of the ith battery at time t, controlled by the ESC through the shared-responsibility battery control signal.","kind":"operational","domain":"Nonnegative real discharging power (kW) within the source-stated inverter limit (Eq. (7)).","unit":"kW","indices":["i","t"],"evidence_ids":["v141-b-g01-e009","v141-b-g01-e011","v141-b-g02-E15"],"source_rule_id":"v141-c-R001","declaration_ref":"19-two_stage_battery_sharing::v141-c-R001::x::v141-c-R001-x002"}],"parameters":[{"parameter_id":"v141-c-R001-theta001","symbol":"W_{B,N}^{i}","meaning":"Nominal capacity (battery size) of the ith battery, used as the normalization basis for the shared-responsibility control rule.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"kWh","indices":["i"],"evidence_ids":["v141-b-g01-e010","v141-b-g02-E15"],"source_rule_id":"v141-c-R001","declaration_ref":"19-two_stage_battery_sharing::v141-c-R001::theta::v141-c-R001-theta001"}]}],"source_definitions":[{"unit_id":"19-two_stage_battery_sharing::v141-a-M01::coordination.local_operator","stage":"L4","subtype":"operator_control_coordination","projection_status":"clear","target_definition":"ESC acts as community market operator and battery controller, coordinates aggregated batteries using PCC net power measurement, sends a common control signal unidirectionally to each battery, organizes customer sharing and import/export balancing with the main grid, and bears price management and settlement management responsibilities.","form_kind":"procedural","identity_fields":["Object: community sharing transactions and participating batteries","Core relationship: a designated operator bears organizational responsibilities and coordinates resources through common measurement and control commands","Output: coordination responsibilities and battery control signals"],"variation_fields":["The operator is ESC, the measurement location is PCC, and communication is unidirectional","Sharing responsibility conditions: P_{BC,t}^i/W_{B,N}^i is equal across batteries, and P_{BD,t}^i/W_{B,N}^i is equal across batteries","Common control is based on community demand and may not act according to an individual prosumer's own net load","ESC is additionally responsible for compensation price adjustment and customer bill management"],"constraint_refs":["19-two_stage_battery_sharing::v141-c-R001::v141-c-R001-C001","19-two_stage_battery_sharing::v141-c-R001::v141-c-R001-C002","19-two_stage_battery_sharing::v141-c-R001::v141-c-R001-C003","19-two_stage_battery_sharing::v141-c-R001::v141-c-R001-C004","19-two_stage_battery_sharing::v141-c-R002::v141-c-R002-C001","19-two_stage_battery_sharing::v141-c-R005::v141-c-R005-C001","19-two_stage_battery_sharing::v141-c-R007::v141-c-R007-C001"],"paper_id":"19-two_stage_battery_sharing","mechanism_id":"v141-a-M01","function":"coordination.local_operator","template_code":"JOC"}],"source_variants":[{"unit_id":"19-two_stage_battery_sharing::v141-a-M01::coordination.local_operator","retained_variants":["ESC organizes customer sharing and import/export balancing with the main grid, and bears price management and settlement management responsibilities","The operator is ESC, the measurement location is PCC, and communication is unidirectional","Coordinates aggregated batteries using PCC net power measurement and sends a common control signal to each battery","Sharing responsibility conditions: P_{BC,t}^i/W_{B,N}^i is equal across batteries, and P_{BD,t}^i/W_{B,N}^i is equal across batteries","Common control is based on community demand and may not act according to an individual prosumer's own net load","ESC is additionally responsible for compensation price adjustment and customer bill management"],"evidence_refs":["19-two_stage_battery_sharing::v141-a-M01::coordination.local_operator::projection"]}],"functional":{"is_child":true,"subdivision_pending":false,"baseline_parent_id":"COMP-ad506099cc3d87b2","baseline_parent_code":"OMC012","secondary_class":"SC-L4-f7de14ccfeeb7f3d","category":{"id":"SC-L4-f7de14ccfeeb7f3d","stage":"L4","label_zh":"Coordination through direct control of aggregated resources","definition_zh":"The coordinator sends control commands to participating resources based on the collective operating state and directly coordinates resource operation to achieve sharing or power balance; incidental market management responsibilities are retained according to the source.","main_identity_axes":["Decision authority: the coordinator directly forms and sends operation control commands","Target object: aggregated resources participating in sharing or balancing","Input-action-output relationship: collective state enters control decision-making and forms resource control signals"],"inclusion_criteria":["There is explicitly a relationship in which the coordinator sends operation control signals to participating resources","Resource control serves collective sharing or power balance"],"exclusion_criteria":["Only economic signals are issued, and participants independently decide equipment operation","Only eligibility for dispatch or resource selection rights is specified; no direct control relationship is explicit","Only bears clearing, matching, or settlement management responsibilities"],"supporting_unit_ids":["19-two_stage_battery_sharing::v141-a-M01::coordination.local_operator"],"status":"agent_defined_structurally_validated"},"definition":{"definition_zh":"The coordinator sends control commands to participating resources based on the collective operating state and directly coordinates resource operation to achieve sharing or power balance; incidental market management responsibilities are retained according to the source.","identity_fields":["Decision authority: the coordinator directly sends resource operation control commands","Target object: aggregated resources participating in sharing or balancing","Input-output relationship: collective operating state enters control decision-making and forms control signals directed to resources"],"member_unit_ids":["19-two_stage_battery_sharing::v141-a-M01::coordination.local_operator"]}},"canonical_pointer":"/nodes/337"});
